//! Schemas of the authoring tools `document_import` and `scene_apply`.
use super::ToolSchema;

/// Most elements one `scene_apply` call may carry (the scene limit).
pub(crate) const MAX_ELEMENTS: usize = 4096;

pub(crate) const SCENE_TOOLS: &[ToolSchema] = &[
    ToolSchema {
        name: "document_import",
        description: "Import a saved .vexel file (inside a granted directory) into the current document as ONE group, in one undoable edit, to reuse a saved character or prop rig. Every id of the file gets idPrefix (default: the file name without extension, made id-safe, plus \"_\"), together with the references to it (href=\"#id\", url(#id), clip, mask, gradient and filter ids), so the same file can be imported many times without clashes; the group itself is named idPrefix without its trailing _ - . and carries transform [tx, ty, rotationDegrees, sx, sy] when given. parentId is \"root\" (default) or a group id. includeTimeline (default true) copies the file's property tracks with ids and targets prefixed (drawing and audio tracks and the camera are not copied; the timeline grows to fit); includeRig (default false) stores the file's rig (bone ids and everything else in the rig that names an element prefixed) in this document, merged into an existing rig (existing roles win). The file passes the same allow-list checks as element_add_fragment: scripts, foreignObject, style, SMIL, event handlers and external references are refused and nothing changes. Not allowed inside a batch. Limits: file source scene at most 4 MiB, 4096 elements in the document in total. Returns groupId, the imported elementIds count, tracks and rig bones. Example: {\"path\":\"/work/chars/kira_rig.vexel\",\"idPrefix\":\"kira_\",\"transform\":[300,500,0,1,1]}.",
        properties: "{\"documentId\":{\"type\":\"string\"},\"path\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":1023},\"parentId\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":128},\"idPrefix\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":64},\"transform\":{\"type\":\"array\",\"minItems\":5,\"maxItems\":5,\"items\":{\"type\":\"number\"}},\"includeTimeline\":{\"type\":\"boolean\",\"default\":true},\"includeRig\":{\"type\":\"boolean\",\"default\":false}}",
        required: "documentId,path",
        fields: "documentId:string;path:string;parentId:string;idPrefix:string;transform:array;includeTimeline:boolean;includeRig:boolean",
    },
    ToolSchema {
        name: "scene_apply",
        description: "Build a whole scene in ONE atomic, undoable call: a nested element tree, property tracks, a rig, the duration and a background. Everything is validated first, applied as one edit and rolled back completely on any error; the message names the failing member, e.g. `elements[12].children[3]: ...` or `tracks[7]: ...`. Calls are additive (ids must be new), so a scene larger than the 2 MiB / 65536 JSON token request limit is split over several calls: elements first (parents before the calls that name them in parentId), then tracks, then rig. elements: up to 4096 entries (all nested ones included); each is an object whose template is rect, ellipse, line or path (the arguments of element_add: attributes, id, opacity, transform, gradientId, paint), text (x, y, content, fontSize, anchor, fill as text_add, plus id), group (id required; opacity, transform; children [...] are created inside it, nested up to 16 deep), use (the arguments of use_add: refId, x, y, fill, stroke, opacity, transform, id) or fragment (xml: one allow-listed XML element as in element_add_fragment, whose ids must be new). A top-level entry may name an existing group in parentId (default root); nested entries go inside their group. tracks: 1-256 entries as native_timeline_tracks_set, applied after the elements, so they may target new ids. rig: the arguments of rig_create (bones, roles), applied after the elements. duration: timeline length in ticks, set before the tracks. background: \"#rrggbb\" adds a full-canvas rect with id scene-background as the first element appended. Counts as 1 + (elements + tracks)/8 requests of the per-minute budget. Not allowed inside a batch. Example: {\"background\":\"#87ceeb\",\"elements\":[{\"template\":\"group\",\"id\":\"hero\",\"children\":[{\"template\":\"rect\",\"id\":\"hero-body\",\"attributes\":{\"x\":\"10\",\"y\":\"10\",\"width\":\"40\",\"height\":\"60\",\"fill\":\"#cc3333\"}}]}],\"tracks\":[{\"trackId\":\"hero-x\",\"targetId\":\"hero\",\"property\":\"transform\",\"valueType\":\"trs\",\"interpolation\":\"linear\",\"value\":[0,0,0,1,1],\"keys\":[{\"tick\":24,\"value\":[100,0,0,1,1]}]}]}.",
        properties: "{\"documentId\":{\"type\":\"string\"},\"elements\":{\"type\":\"array\",\"minItems\":1,\"maxItems\":4096,\"items\":{\"type\":\"object\",\"properties\":{\"template\":{\"type\":\"string\",\"enum\":[\"rect\",\"ellipse\",\"line\",\"path\",\"text\",\"group\",\"use\",\"fragment\"]},\"id\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":128},\"parentId\":{\"type\":\"string\",\"minLength\":1,\"maxLength\":128},\"attributes\":{\"type\":\"object\"},\"opacity\":{\"type\":\"number\",\"minimum\":0,\"maximum\":1},\"transform\":{\"type\":\"object\"},\"gradientId\":{\"type\":\"string\"},\"paint\":{\"type\":\"string\",\"enum\":[\"fill\",\"stroke\"]},\"children\":{\"type\":\"array\"},\"xml\":{\"type\":\"string\",\"maxLength\":1048576}},\"required\":[\"template\"]}},\"tracks\":{\"type\":\"array\",\"minItems\":1,\"maxItems\":256,\"items\":{\"type\":\"object\"}},\"rig\":{\"type\":\"object\"},\"duration\":{\"type\":\"integer\",\"minimum\":1,\"maximum\":4294967295},\"background\":{\"type\":\"string\"}}",
        required: "documentId",
        fields: "documentId:string;elements:array;tracks:array;rig:object;duration:integer;background:string",
    },
];
